<?php

declare(strict_types=1);

namespace Omw\Api\Tests;

use Omw\Api\App;
use Opis\JsonSchema\Errors\ErrorFormatter;
use Opis\JsonSchema\Validator;
use Slim\Psr7\Factory\ServerRequestFactory;

/**
 * Checks PHP output against the JSON Schemas exported from packages/contracts (api/schemas/*.json,
 * generated by `pnpm --filter @omw/contracts schemas`). Skipped while the export is missing.
 */
final class ContractSchemaTest extends TestCase
{
    public function testSeededChangeFeedItemsMatchChangeItem(): void
    {
        $validator = self::validator();
        $db = $this->migratedDb($this->config());

        $rows = $db->all('SELECT seq, entity, entity_key, op, data FROM change_log ORDER BY seq');
        self::assertNotEmpty($rows);
        foreach ($rows as $row) {
            $item = [
                'seq' => (int) $row['seq'],
                'entity' => (string) $row['entity'],
                'key' => (string) $row['entity_key'],
                'op' => (string) $row['op'],
                'data' => json_decode((string) $row['data'], false, 16, JSON_THROW_ON_ERROR),
            ];
            self::assertValid($validator, 'ChangeItem', self::toJsonValue($item));
        }
    }

    public function testSeededSettingsMatchSettings(): void
    {
        $validator = self::validator();
        $db = $this->migratedDb($this->config());

        $settings = [];
        foreach ($db->all('SELECT key, value FROM settings') as $row) {
            $settings[(string) $row['key']] = json_decode((string) $row['value'], false, 16, JSON_THROW_ON_ERROR);
        }
        self::assertValid($validator, 'Settings', self::toJsonValue($settings));
    }

    public function testHealthMatchesHealth(): void
    {
        $validator = self::validator();
        $app = App::create($this->config(['BASE_PATH' => '']));
        $response = $app->handle((new ServerRequestFactory())->createServerRequest('GET', '/api/v1/health'));
        $body = json_decode((string) $response->getBody(), false, 16, JSON_THROW_ON_ERROR);
        self::assertValid($validator, 'Health', $body);
    }

    public function testErrorBodiesMatchApiError(): void
    {
        $validator = self::validator();
        $app = App::create($this->config(['BASE_PATH' => '']));
        $factory = new ServerRequestFactory();

        foreach ([['GET', '/api/v1/nope'], ['POST', '/api/v1/health'], ['GET', '/api/v1/admin/status'], ['POST', '/api/v1/admin/session']] as [$method, $path]) {
            $response = $app->handle($factory->createServerRequest($method, $path));
            $body = json_decode((string) $response->getBody(), false, 16, JSON_THROW_ON_ERROR);
            self::assertValid($validator, 'ApiError', $body, "$method $path");
        }
    }

    private static function validator(): Validator
    {
        $dir = self::rootDir() . '/schemas';
        $index = $dir . '/index.json';
        if (!is_file($index)) {
            self::markTestSkipped('api/schemas/ not generated yet (pnpm --filter @omw/contracts schemas).');
        }
        $meta = json_decode((string) file_get_contents($index), true, 8, JSON_THROW_ON_ERROR);
        self::assertIsArray($meta);
        self::assertSame(App::CONTRACT_VERSION, $meta['contractVersion'] ?? null, 'API and contracts agree on contractVersion');
        self::assertIsString($meta['idPrefix'] ?? null);

        $validator = new Validator();
        $validator->setMaxErrors(5);
        $validator->resolver()?->registerPrefix($meta['idPrefix'], $dir);

        return $validator;
    }

    private static function assertValid(Validator $validator, string $schema, mixed $data, string $label = ''): void
    {
        $meta = json_decode((string) file_get_contents(self::rootDir() . '/schemas/index.json'), true, 8, JSON_THROW_ON_ERROR);
        self::assertIsArray($meta);
        $idPrefix = $meta['idPrefix'];
        self::assertIsString($idPrefix);

        $result = $validator->validate($data, $idPrefix . $schema . '.json');
        $error = $result->error();
        self::assertTrue(
            $result->isValid(),
            trim("$schema $label") . ': ' . ($error === null ? '' : json_encode((new ErrorFormatter())->format($error), JSON_UNESCAPED_SLASHES)) . "\n" . json_encode($data, JSON_UNESCAPED_SLASHES),
        );
    }

    /** Arrays with string keys -> objects, as opis/json-schema expects decoded JSON. */
    private static function toJsonValue(mixed $value): mixed
    {
        return json_decode((string) json_encode($value, JSON_THROW_ON_ERROR), false, 32, JSON_THROW_ON_ERROR);
    }
}
